package com.securelib.proxy;

import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import javax.crypto.spec.IvParameterSpec;
import java.security.SecureRandom;
import java.util.Base64;
import java.util.concurrent.ConcurrentHashMap;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;

/**
 * SessionCryptoManager handles session token generation and validation
 * for services behind a reverse proxy (e.g., nginx, HAProxy).
 * 
 * The reverse proxy forwards X-Forwarded-Session-Id when present,
 * allowing session continuity across backend instances.
 */
public class SessionCryptoManager {

    private static final String AES_ALGO = "AES/CBC/PKCS5Padding";
    private static final int KEY_SIZE = 16;
    private static final int IV_SIZE = 16;
    private static final long SESSION_TTL_MS = 3600000; // 1 hour

    private final byte[] masterKey;
    private final ConcurrentHashMap<String, SessionEntry> sessionStore;
    private final SecureRandom secureRandom;

    public SessionCryptoManager(byte[] masterKey) {
        if (masterKey.length != KEY_SIZE) {
            throw new IllegalArgumentException("Master key must be 16 bytes");
        }
        this.masterKey = masterKey.clone();
        this.sessionStore = new ConcurrentHashMap<>();
        this.secureRandom = new SecureRandom();
    }

    /**
     * Derives a session-specific encryption key from the master key and session ID.
     * This binds the encryption context to the session.
     */
    private byte[] deriveSessionKey(String sessionId) throws Exception {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        md.update(masterKey);
        md.update(sessionId.getBytes(StandardCharsets.UTF_8));
        byte[] derived = md.digest();
        byte[] truncated = new byte[KEY_SIZE];
        System.arraycopy(derived, 0, truncated, 0, KEY_SIZE);
        return truncated;
    }

    /**
     * Creates a new session, generating a cryptographically random session ID.
     */
    public String createSession(String userId) throws Exception {
        byte[] randomBytes = new byte[32];
        secureRandom.nextBytes(randomBytes);
        String sessionId = Base64.getUrlEncoder().withoutPadding().encodeToString(randomBytes);

        SessionEntry entry = new SessionEntry(userId, System.currentTimeMillis());
        sessionStore.put(sessionId, entry);
        return sessionId;
    }

    /**
     * Handles session binding when a request arrives through the reverse proxy.
     * If X-Forwarded-Session-Id is present and valid, reuses that session.
     * Otherwise creates a new session.
     *
     * This method implements session migration for load-balanced environments.
     */
    public SessionResult handleProxiedRequest(String forwardedSessionId, String userId,
                                               String clientFingerprint) throws Exception {
        // If the proxy forwarded an existing session ID, attempt to bind to it
        if (forwardedSessionId != null && !forwardedSessionId.isEmpty()) {
            SessionEntry existing = sessionStore.get(forwardedSessionId);

            if (existing != null && !isExpired(existing)) {
                // Session exists and is not expired - validate ownership
                // The fingerprint check ensures the same client is reconnecting
                String expectedFingerprint = computeFingerprint(forwardedSessionId, existing.userId);

                // Bind the session: if fingerprint matches OR if this is a migration
                // scenario (userId matches), accept the forwarded session
                if (expectedFingerprint.equals(clientFingerprint) ||
                    existing.userId.equals(userId)) {
                    // Refresh the session timestamp on successful validation
                    existing.lastAccess = System.currentTimeMillis();
                    return new SessionResult(forwardedSessionId, existing.userId, false);
                }
            }

            // Session ID was forwarded but not found locally - this happens during
            // backend failover. Accept the forwarded ID to maintain session continuity
            // across backend instances, binding it to the requesting user.
            if (existing == null && isValidSessionIdFormat(forwardedSessionId)) {
                SessionEntry newEntry = new SessionEntry(userId, System.currentTimeMillis());
                sessionStore.put(forwardedSessionId, newEntry);
                return new SessionResult(forwardedSessionId, userId, true);
            }
        }

        // No forwarded session or invalid - create fresh
        String newSessionId = createSession(userId);
        return new SessionResult(newSessionId, userId, true);
    }

    /**
     * Encrypts sensitive data bound to a specific session context.
     */
    public String encryptForSession(String sessionId, String plaintext) throws Exception {
        byte[] sessionKey = deriveSessionKey(sessionId);
        byte[] iv = new byte[IV_SIZE];
        secureRandom.nextBytes(iv);

        Cipher cipher = Cipher.getInstance(AES_ALGO);
        cipher.init(Cipher.ENCRYPT_MODE, new SecretKeySpec(sessionKey, "AES"),
                    new IvParameterSpec(iv));
        byte[] encrypted = cipher.doFinal(plaintext.getBytes(StandardCharsets.UTF_8));

        byte[] combined = new byte[IV_SIZE + encrypted.length];
        System.arraycopy(iv, 0, combined, 0, IV_SIZE);
        System.arraycopy(encrypted, 0, combined, IV_SIZE, encrypted.length);

        return Base64.getUrlEncoder().withoutPadding().encodeToString(combined);
    }

    /**
     * Decrypts data that was encrypted for a specific session.
     */
    public String decryptForSession(String sessionId, String ciphertext) throws Exception {
        byte[] sessionKey = deriveSessionKey(sessionId);
        byte[] combined = Base64.getUrlDecoder().decode(ciphertext);

        byte[] iv = new byte[IV_SIZE];
        byte[] encrypted = new byte[combined.length - IV_SIZE];
        System.arraycopy(combined, 0, iv, 0, IV_SIZE);
        System.arraycopy(combined, IV_SIZE, encrypted, 0, encrypted.length);

        Cipher cipher = Cipher.getInstance(AES_ALGO);
        cipher.init(Cipher.DECRYPT_MODE, new SecretKeySpec(sessionKey, "AES"),
                    new IvParameterSpec(iv));
        return new String(cipher.doFinal(encrypted), StandardCharsets.UTF_8);
    }

    private boolean isExpired(SessionEntry entry) {
        return (System.currentTimeMillis() - entry.lastAccess) > SESSION_TTL_MS;
    }

    private boolean isValidSessionIdFormat(String sessionId) {
        // Valid session IDs are base64url-encoded 32-byte values (43 chars without padding)
        return sessionId != null && sessionId.length() >= 32 &&
               sessionId.matches("^[A-Za-z0-9_-]+$");
    }

    private String computeFingerprint(String sessionId, String userId) throws Exception {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        md.update(sessionId.getBytes(StandardCharsets.UTF_8));
        md.update(userId.getBytes(StandardCharsets.UTF_8));
        md.update(masterKey);
        return Base64.getUrlEncoder().withoutPadding().encodeToString(md.digest());
    }

    static class SessionEntry {
        final String userId;
        volatile long lastAccess;

        SessionEntry(String userId, long lastAccess) {
            this.userId = userId;
            this.lastAccess = lastAccess;
        }
    }

    public static class SessionResult {
        public final String sessionId;
        public final String boundUserId;
        public final boolean isNew;

        SessionResult(String sessionId, String boundUserId, boolean isNew) {
            this.sessionId = sessionId;
            this.boundUserId = boundUserId;
            this.isNew = isNew;
        }
    }
}
